const fs = require('fs');
const readline = require('readline');
const path = require('path');

const brainDir = 'C:/Users/admin/.gemini/antigravity-ide/brain';
const conversations = [
  'fe5f3da4-28e8-4953-b097-ce64bd94b483', // Previous conversation
  '53b57104-e4e2-40d0-adc5-813cc565893f'  // Current conversation
];

const workspaceRoot = 'c:\\users\\admin\\desktop\\billing_inventory';

async function extractEdits() {
  const allEdits = [];

  for (const conv of conversations) {
    const transcriptPath = path.join(brainDir, conv, '.system_generated', 'logs', 'transcript_full.jsonl');
    if (!fs.existsSync(transcriptPath)) {
      console.log(`Transcript not found for conversation: ${conv}`);
      continue;
    }

    console.log(`Parsing transcript for conversation: ${conv}`);
    const fileStream = fs.createReadStream(transcriptPath);
    const rl = readline.createInterface({
      input: fileStream,
      crlfDelay: Infinity
    });

    let currentStep = null;

    for await (const line of rl) {
      if (!line.trim()) continue;
      const step = JSON.parse(line);

      // We look for tool calls made in PLANNER_RESPONSE
      if (step.type === 'PLANNER_RESPONSE' && step.tool_calls) {
        step.tool_calls.forEach(toolCall => {
          const name = toolCall.name || toolCall.toolName;
          const args = toolCall.args || toolCall.arguments;

          if (['replace_file_content', 'multi_replace_file_content', 'write_to_file'].includes(name)) {
            // Check if it targets our workspace
            let targetFile = args.TargetFile;
            if (targetFile) {
              const targetFileLower = targetFile.toLowerCase();
              if (targetFileLower.startsWith(workspaceRoot.toLowerCase()) && 
                  !targetFileLower.includes('implementation_plan.md') && 
                  !targetFileLower.includes('task.md') && 
                  !targetFileLower.includes('walkthrough.md')) {

                allEdits.push({
                  conversation: conv,
                  step_index: step.step_index,
                  tool: name,
                  args: args
                });
              }
            }
          }
        });
      }
    }
  }

  // We sort edits first by conversation order, then by step_index
  // Note: fe5f3da4 comes before 53b57104 chronologically
  const convOrder = {
    'fe5f3da4-28e8-4953-b097-ce64bd94b483': 1,
    '53b57104-e4e2-40d0-adc5-813cc565893f': 2
  };

  allEdits.sort((a, b) => {
    const orderA = convOrder[a.conversation] || 99;
    const orderB = convOrder[b.conversation] || 99;
    if (orderA !== orderB) return orderA - orderB;
    return a.step_index - b.step_index;
  });

  console.log(`Extracted ${allEdits.length} edits across all sessions.`);

  // Group by file
  const fileEdits = {};
  allEdits.forEach(e => {
    const f = e.args.TargetFile;
    if (!fileEdits[f]) fileEdits[f] = [];
    fileEdits[f].push(e);
  });

  console.log('\nEdits per file:');
  for (const f in fileEdits) {
    console.log(`- ${f}: ${fileEdits[f].length} edits`);
    fileEdits[f].forEach((e, idx) => {
      console.log(`  [#${idx+1}] Conv: ${e.conversation.substring(0, 8)} | Step: ${e.step_index} | Tool: ${e.tool}`);
    });
  }

  // Save the extracted edits list to a JSON file in the scratch directory
  const outputPath = path.join(brainDir, '53b57104-e4e2-40d0-adc5-813cc565893f', 'scratch', 'extracted-edits.json');
  fs.writeFileSync(outputPath, JSON.stringify(allEdits, null, 2));
  console.log(`\nSaved extracted edits list to: ${outputPath}`);
}

extractEdits().catch(err => {
  console.error('Failed to extract edits:', err);
});

const fs = require('fs');
const readline = require('readline');
const path = require('path');

const brainDir = 'C:/Users/admin/.gemini/antigravity-ide/brain';
const workspaceRoot = 'c:\\users\\admin\\desktop\\billing_inventory';

async function extractEdits() {
  const allEdits = [];

  // Find all directories in brainDir
  const conversations = fs.readdirSync(brainDir).filter(f => {
    const stat = fs.statSync(path.join(brainDir, f));
    return stat.isDirectory() && f !== 'tempmediaStorage';
  });

  console.log('Found conversation directories:', conversations);

  for (const conv of conversations) {
    const transcriptPath = path.join(brainDir, conv, '.system_generated', 'logs', 'transcript_full.jsonl');
    if (!fs.existsSync(transcriptPath)) {
      console.log(`Transcript not found for conversation: ${conv}`);
      continue;
    }

    console.log(`Parsing transcript for conversation: ${conv}`);
    const fileStream = fs.createReadStream(transcriptPath);
    const rl = readline.createInterface({
      input: fileStream,
      crlfDelay: Infinity
    });

    for await (const line of rl) {
      if (!line.trim()) continue;
      const step = JSON.parse(line);

      // We look for tool calls made in PLANNER_RESPONSE
      if (step.type === 'PLANNER_RESPONSE' && step.tool_calls) {
        step.tool_calls.forEach(toolCall => {
          const name = toolCall.name || toolCall.toolName;
          const args = toolCall.args || toolCall.arguments;

          if (['replace_file_content', 'multi_replace_file_content', 'write_to_file'].includes(name)) {
            // Check if it targets our workspace
            let targetFile = args.TargetFile;
            if (targetFile) {
              const targetFileLower = targetFile.toLowerCase();
              if (targetFileLower.startsWith(workspaceRoot.toLowerCase()) && 
                  !targetFileLower.includes('implementation_plan.md') && 
                  !targetFileLower.includes('task.md') && 
                  !targetFileLower.includes('walkthrough.md')) {

                allEdits.push({
                  conversation: conv,
                  step_index: step.step_index,
                  tool: name,
                  args: args,
                  time: step.timestamp || Date.now() // Use timestamp if available
                });
              }
            }
          }
        });
      }
    }
  }

  // Sort edits globally by step_index and conversation directory time, or keep them grouped
  // Let's sort by timestamp or step_index if from the same conversation
  // Let's get directory stats for order
  const convTimes = {};
  conversations.forEach(c => {
    try {
      convTimes[c] = fs.statSync(path.join(brainDir, c)).birthtimeMs;
    } catch(e) {
      convTimes[c] = 0;
    }
  });

  allEdits.sort((a, b) => {
    const timeA = convTimes[a.conversation] || 0;
    const timeB = convTimes[b.conversation] || 0;
    if (Math.abs(timeA - timeB) > 1000) {
      return timeA - timeB;
    }
    return a.step_index - b.step_index;
  });

  console.log(`Extracted ${allEdits.length} edits across all sessions.`);

  // Group by file
  const fileEdits = {};
  allEdits.forEach(e => {
    const f = e.args.TargetFile;
    if (!fileEdits[f]) fileEdits[f] = [];
    fileEdits[f].push(e);
  });

  console.log('\nEdits per file:');
  for (const f in fileEdits) {
    console.log(`- ${f}: ${fileEdits[f].length} edits`);
    fileEdits[f].forEach((e, idx) => {
      console.log(`  [#${idx+1}] Conv: ${e.conversation.substring(0, 8)} | Step: ${e.step_index} | Tool: ${e.tool}`);
    });
  }

  // Save the extracted edits list to a JSON file in the scratch directory
  const outputPath = path.join(brainDir, '53b57104-e4e2-40d0-adc5-813cc565893f', 'scratch', 'extracted-edits.json');
  fs.writeFileSync(outputPath, JSON.stringify(allEdits, null, 2));
  console.log(`\nSaved extracted edits list to: ${outputPath}`);
}

extractEdits().catch(err => {
  console.error('Failed to extract edits:', err);
});
